// ❌ Required 模式（危险）
var prop = FindProperty("_Color", props);  // 属性不存在直接崩

// ✅ Safe 模式（推荐）
MaterialProperty FindPropertySafe(string name, MaterialProperty[] props)
{
    int idx = FindPropertyIndex(name, props);
    return idx >= 0 ? props[idx] : null;
}
